function renderSub(){ var box=document.getElementById('subBox'); if(!box||!SUBUI)return; var d=SUBUI, me=players[myId], lv=(me&&me.lv)||1; box.innerHTML='';
  var A=d.list[0]||{}, B=d.list[1]||{}, pa=d.pa||0.5;
  var h=document.createElement('div'); h.style.cssText='color:#e0b062;font-weight:bold;margin:2px 0 4px'; h.textContent=d.sub?'🌟 Nhánh: '+(function(){ var S=d.list.find(function(q){return q.id===d.sub;}); return S?(d.subT>=2?S.t2:S.name):''; })():'🌟 Thiên Hướng'; box.appendChild(h);
  var bar=document.createElement('div'); bar.style.cssText='width:100%;height:12px;border:1px solid #6b5636;border-radius:6px;overflow:hidden;display:flex;background:#100a06';
  bar.innerHTML='<div style="width:'+Math.round(pa*100)+'%;background:linear-gradient(90deg,'+A.col+'aa,'+A.col+')"></div><div style="flex:1;background:linear-gradient(90deg,'+B.col+','+B.col+'aa)"></div>'; box.appendChild(bar);
  var lab=document.createElement('div'); lab.style.cssText='width:100%;display:flex;justify-content:space-between;font-size:10px;margin:2px 0 6px';
  lab.innerHTML='<span style="color:'+A.col+'">'+A.name+' '+Math.round(pa*100)+'%</span><span style="color:'+B.col+'">'+Math.round((1-pa)*100)+'% '+B.name+'</span>'; box.appendChild(lab);
  var note=document.createElement('div'); note.className='pd'; note.style.cssText='font-size:10px;color:#b8a888;margin-bottom:4px';
  note.textContent=lv<d.lv1?('Cộng điểm & nâng kỹ năng theo hướng nào thì tới cấp '+d.lv1+' nhân vật sẽ tự THỨC TỈNH theo hướng đó. Build càng thuần, sức mạnh nhánh càng lớn.')
    :(d.sub?('Sức mạnh nhánh: '+Math.round((d.pow||0)*100)+'% (build càng thuần càng mạnh)'+(d.subT<2?' · Tới cấp '+d.lv2+' với build ≥62% sẽ THĂNG HOA.':'')+' · Nếu build nghiêng hẳn sang hướng kia (≥62%) sẽ CHUYỂN HƯỚNG.'):'Build còn lưng chừng — cần nghiêng ≥56% về một phía để thức tỉnh.');
  box.appendChild(note);
  [A,B].forEach(function(S){ var r=document.createElement('div'); r.style.cssText='font-size:10px;color:#c8b48a;text-align:left;width:100%;margin:2px 0'; r.innerHTML='<b style="color:'+S.col+'">'+S.name+' → '+S.t2+'</b>: '+S.desc; box.appendChild(r); }); }
function renderChr(){
  if(false){ var sbx=document.createElement('div'); sbx.id='subBox'; sbx.style.cssText='width:100%;max-width:360px;display:flex;flex-direction:column;align-items:center;margin-bottom:8px;border:1px solid #6b5636;border-radius:8px;padding:6px;background:#1b140d'; var pb0=document.getElementById('pasvBox'); pb0.parentNode.insertBefore(sbx,pb0.nextSibling); ws.send(JSON.stringify({t:'subinfo'})); }
  var pb=document.getElementById('pasvBox');
  pb.innerHTML=myPassive?('<b>'+myPassive.name+'</b><br>'+myPassive.desc):'Chưa chọn class';
  var myPk=(players[myId]&&players[myId].pkScore)||0, myJail=(players[myId]&&players[myId].jailed)||0;
  if(myPk>0){
    var pkSec=document.getElementById('pkSecChr');
    if(!pkSec){ pkSec=document.createElement('div'); pkSec.id='pkSecChr'; pkSec.style.cssText='max-width:320px;width:100%;background:#2a1512;border:1px solid #b8514d;border-radius:8px;padding:10px;margin-bottom:10px;text-align:center';
      pb.parentNode.insertBefore(pkSec, pb); }
    pkSec.innerHTML='<div style="color:#ff9a8a;font-size:12px;margin-bottom:6px">☠️ Điểm PK: '+Math.round(myPk)+(myJail>0?' · Đang tự thú ('+Math.round(myJail)+'s)':'')+'</div>';
    if(myJail<=0){ var tuThuBtn=document.createElement('button'); tuThuBtn.textContent='🔒 Tự Thú (giảm PK nhanh 60s)';
      tuThuBtn.style.cssText='padding:7px 16px;border-radius:7px;border:1px solid #ff9a8a;background:#3a1a15;color:#ffb0a0;font-size:11px';
      tuThuBtn.addEventListener('pointerdown',function(ev){ev.preventDefault();ws.send(JSON.stringify({t:'tuthu'}));});
      pkSec.appendChild(tuThuBtn); }
  } else { var old=document.getElementById('pkSecChr'); if(old)old.remove(); }
  document.getElementById('ptsline').textContent='Điểm chỉ số: '+myBuild.statPts+' · Điểm skill: '+myBuild.skillPts;
  var sg=document.getElementById('statgrid'); sg.innerHTML='';
  ['STR','VIT','AGI','INT'].forEach(function(st){
    var row=document.createElement('div'); row.className='statrow';
    row.innerHTML='<span class="sn">'+STATNAME[st]+'</span><span class="sv">'+(myBuild[st]||0)+'</span>';
    var btn=document.createElement('button'); btn.textContent='+'; btn.disabled=myBuild.statPts<=0;
    btn.addEventListener('pointerdown',function(ev){ev.preventDefault();ws.send(JSON.stringify({t:'allocstat',stat:st}));});
    row.appendChild(btn); sg.appendChild(row);
  });
  var skg=document.getElementById('skgrid'); skg.innerHTML='';
  var hdr=document.createElement('div'); hdr.style.cssText='font-size:11px;color:#9a8a6a;margin:4px 0 6px;max-width:340px;width:100%';
  hdr.textContent='Kỹ Năng'; skg.appendChild(hdr);
  var myLv=(players[myId]&&players[myId].lv)||1;
  var STATLBL={STR:'Sức Mạnh',VIT:'Sinh Lực',AGI:'Nhanh Nhẹn',INT:'Trí Tuệ'};
  var _lastBr=-2;
  myFull.slice().sort(function(a,b){ var ka=(a.br<0?-1:a.br), kb=(b.br<0?-1:b.br); return ka-kb||a.unlockLv-b.unlockLv; }).forEach(function(s){
    if(myTree&&s.br!==_lastBr){ _lastBr=s.br; var hh=document.createElement('div'); hh.className='skhead';
      if(s.br<0) hh.innerHTML='<b>Kỹ Năng Gốc</b><span>'+myTree.core+'/'+myTree.need+' bậc để mở nhánh · tổng điểm cấp 200: 209</span>';
      else { var chosen=(myTree.br===s.br), other=(myTree.br!==null&&myTree.br!==s.br); hh.style.borderColor=myTree.cols[s.br];
        hh.innerHTML='<b style="color:'+myTree.cols[s.br]+'">'+myTree.names[s.br]+'</b><span>Đã đầu tư '+((myTree.inv&&myTree.inv[s.br])||0)+' điểm</span>'; }
      skg.appendChild(hh); }
    var unl = !s.lock;
    var lockReason = s.lock==='core'?'🔒 Cần '+(myTree?myTree.need:10)+' bậc kỹ năng gốc':(false?'':(s.lock==='stat'?('🔒 Cần '+s.reqVal+' '+STATLBL[s.reqStat]):(s.lock?('🔒 '+s.lock):'')));
    var row=document.createElement('div'); row.className='skrow2'+(unl?'':' locked');
    var equippedSlot=null; for(var k in myLoadout){ if(myLoadout[k]===s.id)equippedSlot=k; }
    var branchTag = s.reqStat ? ('<span style="font-size:9px;color:#9a8a6a"> · nhánh '+STATLBL[s.reqStat]+'</span>') : '';
    var _sic=icoCSS('sk:'+s.id,28);
    row.innerHTML='<div class="sk2top"><span class="si">'+(_sic?'<div style="border-radius:6px;'+_sic+'"></div>':s.icon)+'</span><span class="sname">'+s.name+branchTag+(s.st?' <i style="font-style:normal;font-size:9.5px;color:'+({STR:'#ff9a7a',AGI:'#8effc1',INT:'#8fc4ff',VIT:'#ffd76b',BLD:'#e0a0ff'}[s.st])+'">'+({STR:'Sức Mạnh',AGI:'Nhanh Nhẹn',INT:'Trí Tuệ',VIT:'Sinh Lực',BLD:'Sức Mạnh / Trí Tuệ'}[s.st])+'</i>':'')+'</span>'+
      (unl?('<span class="sr">'+(s.ult?'<b style="color:#ffb347">Tuyệt kỹ</b> · ':'')+'Bậc '+s.rank+'/'+(s.max||10)+'</span>'):('<span class="sr">'+lockReason+'</span>'));
    if(s.desc){ var descEl=document.createElement('div'); descEl.style.cssText='font-size:10.5px;color:#b8a888;margin:4px 0 6px;line-height:1.4';
      descEl.textContent=s.desc; row.appendChild(descEl); }
    var _st=(s.max===5)?2.25:1;
    if(unl && s.scaleKey && s.rank<(s.max||10)){
      var curMul=1+(s.rank-1)*_st*0.15, nextMul=1+(s.rank)*_st*0.15;
      var prevEl=document.createElement('div'); prevEl.style.cssText='font-size:10px;color:#e0b062;margin-bottom:6px';
      prevEl.textContent='Bậc '+(s.rank+1)+': '+Math.round(curMul*100)+'% → '+Math.round(nextMul*100)+'%';
      row.appendChild(prevEl);
    } else if(unl && s.scaleKey && s.rank>=(s.max||10)){
      var maxEl=document.createElement('div'); maxEl.style.cssText='font-size:10px;color:#7a9a6a;margin-bottom:6px';
      maxEl.textContent='Tối đa (235%)'; row.appendChild(maxEl);
    }
    var rowEl=row;
    var slotWrap=document.createElement('div'); slotWrap.className='sk2slots';
    if(unl){
      ['q','w','e','r'].forEach(function(slot){
        var sb=document.createElement('button'); sb.textContent=slot.toUpperCase();
        sb.className='slotbtn'+(equippedSlot===slot?' active':'');
        sb.addEventListener('pointerdown',function(ev){ev.preventDefault();ws.send(JSON.stringify({t:'setloadout',slot:slot,skillId:s.id}));});
        slotWrap.appendChild(sb);
      });
      var rb=document.createElement('button'); rb.className='rankbtn'; rb.textContent=s.rank>=(s.max||10)?'Tối đa':('▲ Nâng · '+(s.cost||1)+' điểm');
      rb.disabled=(myBuild.skillPts<(s.cost||1)||s.rank>=(s.max||10));
      rb.addEventListener('pointerdown',function(ev){ev.preventDefault();ws.send(JSON.stringify({t:'rankskill',skillId:s.id}));});
      slotWrap.appendChild(rb);
    }
    rowEl.appendChild(slotWrap);
    skg.appendChild(rowEl);
  });
  if(myTree&&myTree.cmb&&myTree.cmb.length){ var ch=document.createElement('div'); ch.className='skhead'; ch.innerHTML='<b>Liên Hoàn</b><span>dùng liền nhau trong 3.5 giây</span>'; skg.appendChild(ch);
    myTree.cmb.forEach(function(q){ var off=q.s.some(function(id){ var f=null; myFull.forEach(function(x){ if(x.id===id)f=x; }); return !f||f.lock; }); var r=document.createElement('div'); r.className='skrow2'; r.style.cssText='max-width:340px;width:100%;display:flex;align-items:center;gap:6px;padding:5px 8px;margin-bottom:4px'+(off?';opacity:.4':'');
      var ic=q.s.map(function(id){ var f=null; myFull.forEach(function(x){ if(x.id===id)f=x; }); return '<span title="'+(f?f.name:id)+'" style="font-size:18px">'+(f?f.icon:'?')+'</span>'; }).join('<b style="color:#a87b3e">›</b>');
      var col=q.b<0?'#ffd98a':myTree.cols[q.b]; r.innerHTML='<div style="flex:1;color:'+col+';font-weight:bold;font-size:12px">'+q.n+'<div style="font-weight:normal;color:#b8a888;font-size:10px">+'+Math.round((q.m-1)*100)+'% sát thương 1.5 giây · hồi 5% máu</div></div>'+ic; skg.appendChild(r); }); }
}
