  var _G=it.set?GSETS.find(function(x){return x.id===it.set;}):null; var top='<b class="inm r'+_ra+(_G?' iset':'')+((it.plus||0)>=11?' ihi':'')+'" style="color:'+(_G?_G.col:_tc)+';--gc:'+(_G?_G.col:_tc)+'">'+(_ra>=1?'['+RARN[_ra]+'] ':'')+(_lk?_lk.n:SLOTNAME[it.slot])+'</b> <span style="color:#9a8a6a">'+SLOTNAME[it.slot]+(it.slot==='wing'?' · Cấp '+(it.wl||it.tier):' · '+'★'.repeat(it.tier||1))+'</span>'+(pl>0?' <b style="color:#ffd76b">+'+pl+'</b>':'')+' · '+statTxt+(it.hpB?' · ❤️ +'+it.hpB:'')+
    ((it.opts&&it.opts.length)?'<br>'+it.opts.map(function(o){return '<span style="color:'+_tc+'">◆ '+(EXTXT[o]||o)+'</span>';}).join(' '):'')+reqHTML(it);
  var cost=eCost(it), need=eStones(it), rate=Math.round(eRate(pl)*100), maxed=pl>=MAXPLUS, poor=(gold<cost||stones<need);
