(function(){ var rl=null, go=false; try{ rl=JSON.parse(sessionStorage.getItem('relog')||'null'); go=sessionStorage.getItem('toSelect')==='1'; sessionStorage.removeItem('toSelect'); }catch(e){}
  if(rl&&go){ document.getElementById('userInput').value=rl[0]; document.getElementById('passInput').value=rl[1]; var tr=0, iv=setInterval(function(){ if(ws.readyState===1||++tr>40){ clearInterval(iv); submitLogin(); } },150); } })();
document.getElementById('passInput').addEventListener('keydown',function(ev){if(ev.key==='Enter')submitLogin();});
