document.getElementById('pickBack').addEventListener('pointerdown',function(e){e.preventDefault(); if(!SLOTS.length&&!document.getElementById('slotCards').children.length)return; document.getElementById('pick').style.display='none'; document.getElementById('slotScr').style.display='flex'; renderSlots(SLOTS);});
