var myPots={}, POTCAT=[], QB=['hp*','mp*','elxA','elxD'], QBCD={}, myBuf={A:0,D:0,t:0};
try{ var _q=JSON.parse(localStorage.getItem('qb2')||'null'); if(_q&&_q.length===4)QB=_q; }catch(e){}
function qbResolve(k){ if(k==='hp*'||k==='mp*'){ var f=k==='hp*'?'hp':'mp', best=null; POTCAT.forEach(function(c){ if(c[f]&&(myPots[c.id]||0)>0&&(!best||c[f]>best[f]))best=c; });
    if(!best) POTCAT.forEach(function(c){ if(c[f]&&(!best||c[f]<best[f]))best=c; }); return best; }
  for(var i=0;i<POTCAT.length;i++) if(POTCAT[i].id===k) return POTCAT[i]; return null; }
function qbGrp(c){ return c.hp?'h':(c.mp?'m':'b'+c.b); }
function qbRender(){ var bar=document.getElementById('quickBar'); if(!bar)return; if(bar.children.length!==4){ bar.innerHTML=''; for(var i=0;i<4;i++){ (function(i){ var d=document.createElement('div'); d.className='qs';
      d.innerHTML='<div class="qi"></div><span class="qk">'+(i+1)+'</span><span class="qn"></span><div class="cd"></div>';
      var lp=null, fired=false;
      d.addEventListener('pointerdown',function(ev){ ev.preventDefault(); ev.stopPropagation(); fired=false; lp=setTimeout(function(){ fired=true; qbPicker(i,d); },480); });
      d.addEventListener('pointerup',function(ev){ ev.preventDefault(); ev.stopPropagation(); if(lp){clearTimeout(lp);lp=null;} if(!fired) qbUse(i); });
      d.addEventListener('pointerleave',function(){ if(lp){clearTimeout(lp);lp=null;} });
      bar.appendChild(d); })(i); } }
  for(var j=0;j<4;j++){ var d=bar.children[j], c=qbResolve(QB[j]); var qi=d.querySelector('.qi'), qn=d.querySelector('.qn');
    if(!c){ qi.style.cssText=''; qn.textContent=''; d.classList.add('none'); continue; }
    var cs=icoCSS('it:'+(c.ico||c.id),36); qi.style.cssText=cs||''; qi.style.position='absolute'; qi.style.left='5px'; qi.style.top='5px';
    var n=myPots[c.id]||0; qn.textContent=n; d.classList.toggle('none',n<=0);
    var bt=c.b==='A'?myBuf.A:(c.b==='D'?myBuf.D:0); d.classList.toggle('on',bt>0&&(performance.now()-myBuf.t)<bt); d.title=c.n; } }
function qbUse(i){ var c=qbResolve(QB[i]); if(!c)return; if(!(myPots[c.id]>0)){ ctoast('Hết '+c.n); return; }
  var g=qbGrp(c), now=performance.now(); if((QBCD[g]||0)>now)return; QBCD[g]=now+(g.charAt(0)==='b'?1000:1200); QBCD[g+'_s']=now;
  if(ws&&ws.readyState===1)ws.send(JSON.stringify({t:'usepot',k:c.id})); }
function qbPicker(i,el){ var p=document.getElementById('qbPick'); var h='<div style="color:#e0b062;font-size:11px;margin-bottom:4px">Ô '+(i+1)+' — chọn vật phẩm</div>';
  var opts=[{k:'hp*',n:'Bình máu tốt nhất',ico:'hp'},{k:'mp*',n:'Bình mana tốt nhất',ico:'mp'}].concat(POTCAT.map(function(c){return {k:c.id,n:c.n,ico:c.ico,c:myPots[c.id]||0};}));
  opts.forEach(function(o){ var cs=icoCSS('it:'+o.ico,24); h+='<div class="qo" data-k="'+o.k+'">'+(cs?'<div style="flex:0 0 auto;'+cs+'"></div>':'')+'<span style="flex:1">'+o.n+'</span>'+(o.c!==undefined?'<b style="color:#ffd76b">'+o.c+'</b>':'')+'</div>'; });
  p.innerHTML=h; p.style.display='block'; var rc=el.getBoundingClientRect(); p.style.left=Math.min(innerWidth-270,rc.right+8)+'px'; p.style.top=Math.max(4,Math.min(innerHeight-p.offsetHeight-4,rc.top-p.offsetHeight/2))+'px';
  p.querySelectorAll('.qo').forEach(function(q){ q.onpointerdown=function(ev){ ev.preventDefault(); ev.stopPropagation(); QB[i]=q.getAttribute('data-k'); try{localStorage.setItem('qb2',JSON.stringify(QB));}catch(e){} p.style.display='none'; qbRender(); }; }); }
document.addEventListener('pointerdown',function(e){ var p=document.getElementById('qbPick'); if(p&&p.style.display==='block'&&!p.contains(e.target)) p.style.display='none'; },true);
