  if(ZONE_DECOR[myZone]&&!ZONE_DECOR[myZone]._edge&&ZONEDATA[myZone]&&ZONEDATA[myZone].w){ addEdge(ZONE_DECOR[myZone],myZone); ZONE_DECOR[myZone]._edge=1;
    var _DL=ZONE_DECOR[myZone]; for(var _q=_DL.length-1;_q>=0;_q--){ if(!_DL[_q].edge&&wallC(myZone,_DL[_q].x,_DL[_q].y)) _DL.splice(_q,1); } addSolids(_DL,myZone); }
