  var BOSS_GRID=['..o...o..','.oo.o.oo.','..ooooo..','.oo.o.oo.','..ooooo..','...ooo...','.ooooooo.','ooooooooo','ooooooooo','ooooooooo','.ooooooo.','o.o...o.o','o.o...o.o'];
