  enemies[id]={x,y,zone,hp,maxhp:hp,spd:Math.round(52*mt.spdMul*(el?1.1:1)),atk:0,dead:false,respawnT:0,xp:Math.round(20*Math.pow(tier,1.35)*(el?5:1)),gold:6*tier*(el?5:1),r:el?19:14,boss:false,
    dmg:Math.round(6*Math.pow(tier,1.05)*mt.dmgMul*(el?1.6:1)),mtype:mt.id,mname:(el?'⚜ ':'')+mt.name+(el?' Tinh Anh':''),mhue:mt.hue,mshape:mt.shape,rng:(RANGED[(mt.shape||'').replace('h:','')]?1:undefined),elite:el||undefined,
    camp:camp?ci:undefined,homeX:Math.round(x),homeY:Math.round(y),rover:camp?undefined:true,aggroT:0,wT:Math.random()*3};
