    for(let k=0;k<n;k++){ const a=a0+(k-(n-1)/2)*0.36; t=hz(e,{sh:'line',x:e.x,y:e.y,x2:e.x+Math.cos(a)*540,y2:e.y+Math.sin(a)*540,w:52,kb:50},1.0,1.1); }
