      if(port.lv&&(p.lv||1)<port.lv){ if(p._lvWarn!==port.to){ p._lvWarn=port.to; sendTo(id,{t:'toast',text:'⛔ Cần cấp '+port.lv+' để vào '+(ZONES[port.to]?ZONES[port.to].name:port.label)}); } continue; }
      p._lvWarn=null;
